head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[tabs > P > id]<br/>컴포넌트의 ID 를 설정합니다.",
    "validation" : [
        "동일 Scope 에서 컴포넌트 모듈을 구별할 수 있는 유일값을 문자열로 설정 할 수 있어야 합니다.",
        "미 설정 시 렌더링 과정에서 내부 규칙에 의한 임의의 ID 가 설정되어야 합니다.",        
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {
        id: con_ID.getValue(),
    };

    let cList = $c.gcm.createCList(properties);       

    let grp_comp = $c.gcm.getTestGroup();    
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:tabControl ' + strNameSpace + ' id="" alwaysDraw="false" style="width:500px;height:200px;">';
    strTarget += '<w2:tabs ' + cList + ' disabled="false" style="height:40px;" label="Tabs1"></w2:tabs>';
    strTarget += '<w2:tabs disabled="false" style="height:40px" id="tabs2" label="Tabs2"></w2:tabs>';
    strTarget += '<w2:tabs disabled="false" style="height:40px" id="tabs3" label="Tabs3"></w2:tabs>';
    strTarget += '<w2:content alwaysDraw="false" style="height:160px;" id="content1">';
    strTarget += '<w2:button style="width:130px; height:50px;" id="content1_child" label="content1_child"></w2:button>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content alwaysDraw="false" style="height:160px" id="content2">';
    strTarget += '<xf:input id="content2_child" style="width:144px; height:21px; " initValue="content2_child"></xf:input>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content style="height:160px" id="content3">';
    strTarget += '<w2:textbox id="content3_child" label="content3_child" style="width:200px; height:50px; background-color:var(--ws-gray-300);"></w2:textbox>';
    strTarget += '</w2:content>';  
    strTarget += '</w2:tabControl>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "tabControl",
        strTarget,
        grp_comp
    );
}



scwin.btn_getID_onclick = function (e) {
    let tabs1 = document.querySelector('li[id*="target1_tab"]');

    if (tabs1) {
        let rtn = tabs1.id;
        wf_body_bottom.getObj("scwin").setReturnValue("getID : " + rtn);  
    }   
};
